import{_ as d,o as e,c as r,a3 as o}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"项目结构与职责","description":"","frontmatter":{},"headers":[],"relativePath":"developer/project-structure.md","filePath":"developer/project-structure.md"}'),c={name:"developer/project-structure.md"};function a(s,t,n,i,l,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="项目结构与职责" tabindex="-1">项目结构与职责 <a class="header-anchor" href="#项目结构与职责" aria-label="Permalink to &quot;项目结构与职责&quot;">​</a></h1><h2 id="仓库目录" tabindex="-1">仓库目录 <a class="header-anchor" href="#仓库目录" aria-label="Permalink to &quot;仓库目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th><th>职责</th></tr></thead><tbody><tr><td><code>frontend/src/</code></td><td>Vue 3、TypeScript、Pinia、antdv-next、Tailwind CSS 4 前端</td></tr><tr><td><code>frontend/tests/</code></td><td>前端单元、集成、端到端测试和测试支持代码</td></tr><tr><td><code>backend/src/</code></td><td>Tauri 桌面宿主、应用编排和产品业务模块</td></tr><tr><td><code>backend/crates/</code></td><td>可复用 Rust SDK 库</td></tr><tr><td><code>backend/tests/</code></td><td>Rust 单元、集成测试及支持代码</td></tr><tr><td><code>scripts/</code></td><td>仓库级启动、打包、架构与 SDK 检查脚本</td></tr><tr><td><code>scripts/tests/</code></td><td>桌面环境与启动脚本测试</td></tr><tr><td><code>docs/</code></td><td>文档和资源；当前文档站位于 <code>docs/guide/</code></td></tr><tr><td><code>legacy/frontend/</code>、<code>legacy/backend/</code></td><td>本地旧实现归档，已忽略且不参与当前检查</td></tr></tbody></table><p>JavaScript 依赖与前端工具配置归属 <code>frontend/</code>；Cargo、Tauri 配置和平台资源归属 <code>backend/</code>。根目录脚本负责协调各项目。</p><h2 id="前端调用边界" tabindex="-1">前端调用边界 <a class="header-anchor" href="#前端调用边界" aria-label="Permalink to &quot;前端调用边界&quot;">​</a></h2><p>页面通过 <code>frontend/src/api/</code> 中的统一接口层调用后端。<code>call-backend.ts</code> 负责调用入口，浏览器开发环境接入 mock；Tauri 环境执行实际命令。后端状态变化通过事件通知前端重新读取快照。</p><p>共享纯类型放入 <code>frontend/src/types/</code>，组合式函数放入 <code>composables/</code>，纯工具函数放入 <code>utils/</code>。功能内部使用的内容保留在功能目录内，不创建 <code>frontend/src/shared/</code>。</p><h2 id="后端层次" tabindex="-1">后端层次 <a class="header-anchor" href="#后端层次" aria-label="Permalink to &quot;后端层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>职责</th></tr></thead><tbody><tr><td><code>backend/src/desktop/</code></td><td>托盘、窗口、系统能力与桌面环境接入</td></tr><tr><td><code>backend/src/application/</code></td><td>启动恢复、依赖组装、任务编排、快照与跨模块协作</td></tr><tr><td><code>backend/src/modules/configuration/</code></td><td>应用配置</td></tr><tr><td><code>backend/src/modules/sites/</code></td><td>站点、凭据、模型与请求策略</td></tr><tr><td><code>backend/src/modules/monitoring/</code></td><td>正式探测、健康状态和探测历史</td></tr><tr><td><code>backend/src/modules/iq_test/</code></td><td>题库、测试任务、历史与输出回放</td></tr></tbody></table><p>产品业务保留在宿主模块；公共 SDK 不依赖 Tauri 或宿主产品模块。</p><h2 id="公共-sdk-依赖" tabindex="-1">公共 SDK 依赖 <a class="header-anchor" href="#公共-sdk-依赖" aria-label="Permalink to &quot;公共 SDK 依赖&quot;">​</a></h2><p>以下为仓库内公共库之间允许的生产依赖，具体约束由 <code>scripts/check-architecture.mjs</code> 检查：</p><table tabindex="0"><thead><tr><th>公共库</th><th>允许依赖的公共库</th></tr></thead><tbody><tr><td><code>relaypulse-runtime</code></td><td>无</td></tr><tr><td><code>relaypulse-model-client</code></td><td>runtime</td></tr><tr><td><code>relaypulse-storage</code></td><td>runtime</td></tr><tr><td><code>relaypulse-diagnostics</code></td><td>runtime</td></tr><tr><td><code>relaypulse-operations</code></td><td>runtime、storage</td></tr><tr><td><code>relaypulse-notifications</code></td><td>storage、diagnostics</td></tr></tbody></table><p>修改公共 API 或模块依赖后，执行<a href="./checks-and-tests.html#架构与-sdk">架构与 SDK 检查</a>。</p>',14)])])}const b=d(c,[["render",a]]);export{u as __pageData,b as default};
